<script setup>
import { computed, nextTick, onMounted, onUnmounted, ref } from 'vue'
import { api, clearSession, normalizeUser, uploadFile } from './api.js'
import { demoComments, demoPosts } from './demo.js'

const tabs=[['recommended','推荐'],['latest','最新'],['global','全局']]
const tab=ref('recommended'), posts=ref([]), status=ref('loading'), error=ref(''), demoMode=ref(false)
const viewer=ref(null), loginOpen=ref(false), composerOpen=ref(false), detail=ref(null), comments=ref([])
const draft=ref(localStorage.getItem('fanbbs_draft')||''), busy=ref(false), toast=ref(''), query=ref(''), loginError=ref('')
const selectedFiles=ref([])
const view=ref('home'), authMode=ref('login'), categories=ref([]), results=ref([]), resultUsers=ref([]), resultTags=ref([]), bookmarks=ref([]), notifications=ref([]), adminQueue=ref([]), sectionError=ref(''), detailOrigin=ref('#home')
const messageMode=ref('notifications'), conversations=ref([]), activeConversation=ref(null), messages=ref([])
const conversationCursor=ref(''), messageCursor=ref(''), eventCursor=ref('');let eventTimer
const adminMode=ref('reports'), adminUsers=ref([]), adminContent=ref([]), adminTaxonomy=ref({categories:[],tags:[]})
const adminContentFilter=ref({status:'published',type:'',q:''})
const publicProfile=ref(null), socialList=ref([]), deviceSessions=ref([]), feedFilters=ref({})
const homepage=ref({carousel:[],announcements:[]}), homepageAdmin=ref(null)
const productTypes=ref([]), products=ref([]), cart=ref([]), orders=ref([]), game=ref(null), pointEvents=ref([]), tasks=ref([]), ranks=ref([]), frames=ref([])
const pendingPosts=new Set()
const visiblePosts=computed(()=>posts.value.filter(p=>`${p.author.name} ${p.author.handle} ${p.content}`.toLowerCase().includes(query.value.toLowerCase())))

function announce(message){ toast.value=message; setTimeout(()=>{if(toast.value===message)toast.value=''},2600) }
async function loadFeed(){ status.value='loading'; error.value=''; try { const r=await api.feed(tab.value,feedFilters.value); posts.value=r.data||[]; demoMode.value=false;status.value=posts.value.length?'ready':'empty' } catch(e){error.value=e.message;if(e.code==='network_error'){posts.value=demoPosts.map(p=>({...p}));demoMode.value=true;status.value='ready'}else{posts.value=[];demoMode.value=false;status.value='error'}} }
async function changeTab(value){ tab.value=value; await loadFeed() }
async function navigate(target){ detail.value=null;view.value=target;sectionError.value='';history.replaceState({},'',`#${target}`);try{if(target==='discover'){categories.value=(await api.categories()).data||[]}if(target==='saved')bookmarks.value=(await api.bookmarks()).data||[];if(target==='messages'){messageMode.value='notifications';notifications.value=(await api.notifications()).data||[]}if(target==='me')deviceSessions.value=(await api.sessions()).data||[];if(target==='admin')adminQueue.value=(await api.adminReview()).data||[]}catch(e){sectionError.value=e.message} }
function requireAuth(action){ if(!viewer.value){loginOpen.value=true; nextTick(()=>document.querySelector('#identity')?.focus()); return false} action(); return true }
function storeSession(data){sessionStorage.setItem('fanbbs_access_token',data.access_token);if(data.refresh_token)sessionStorage.setItem('fanbbs_refresh_token',data.refresh_token);viewer.value=normalizeUser(data.user);sessionStorage.setItem('fanbbs_user',JSON.stringify(viewer.value))}
async function doLogin(e){ busy.value=true;loginError.value=''; const f=new FormData(e.currentTarget); try{const r=await api.login(f.get('identity'),f.get('password'));storeSession(r.data);loginOpen.value=false;announce('登录成功')}catch(err){if(err.code==='network_error'&&demoMode.value&&f.get('identity')&&f.get('password')){viewer.value={name:'旅行者',handle:'traveler'};loginOpen.value=false;announce('已进入本地预览模式')}else loginError.value=err.message}finally{busy.value=false}}
async function doRegister(e){busy.value=true;loginError.value='';const f=new FormData(e.currentTarget);try{const r=await api.register(f.get('handle'),f.get('email'),f.get('display_name'),f.get('password'));storeSession(r.data);loginOpen.value=false;announce('账号创建成功')}catch(err){loginError.value=err.message}finally{busy.value=false}}
async function logout(){try{await api.logout()}catch{}clearSession();viewer.value=null;navigate('home');announce('已退出登录')}
function closeDialog(kind){ if(kind==='compose'&&draft.value.trim()&&!confirm('草稿尚未发布，确定关闭吗？'))return; loginOpen.value=false;composerOpen.value=false }
function selectMedia(e){selectedFiles.value=Array.from(e.target.files||[]).slice(0,8)}
async function publish(){if(!draft.value.trim())return;busy.value=true;error.value='';try{let p;if(demoMode.value)p={...demoPosts[0],id:`local-${Date.now()}`,content:draft.value,author:viewer.value,age:'刚刚',comments:0,reposts:0,likes:0,views:0,avatar:'旅'};else{const mediaIds=[];for(const file of selectedFiles.value)mediaIds.push((await uploadFile(file,{altText:file.name})).data.id);p=(await api.createPost(draft.value,mediaIds)).data}posts.value.unshift(p);draft.value='';selectedFiles.value=[];localStorage.removeItem('fanbbs_draft');composerOpen.value=false;announce('帖子已发布')}catch(e){error.value=e.message}finally{busy.value=false}}
async function toggleLike(post){requireAuth(async()=>{const key=`like:${post.id}`;if(pendingPosts.has(key))return;pendingPosts.add(key);const was=post.liked;post.liked=!was;post.likes+=was?-1:1;try{if(!demoMode.value){const r=await api.like(post.id,was);post.liked=r.data.liked;post.likes=r.data.like_count}}catch(e){post.liked=was;post.likes+=was?1:-1;announce(e.message)}finally{pendingPosts.delete(key)}})}
async function repost(post){requireAuth(async()=>{const key=`repost:${post.id}`;if(pendingPosts.has(key))return;if(post.reposted){announce('已经转发过这条帖子');return}pendingPosts.add(key);try{await api.repost(post.id);post.reposted=true;post.reposts++;announce('已转发')}catch(e){announce(e.message)}finally{pendingPosts.delete(key)}})}
async function loadDetail(id,fallback=null){status.value='loading';detail.value=fallback;comments.value=[];try{if(!demoMode.value)detail.value=(await api.detail(id)).data;else detail.value=fallback||demoPosts.find(p=>p.id===id);if(!detail.value)throw new Error('帖子不存在');comments.value=demoMode.value?demoComments:(await api.comments(id)).data||[];status.value='ready'}catch(e){detail.value=null;status.value='error';error.value=e.message}nextTick(()=>document.querySelector('.detail-title')?.focus())}
async function openDetail(post){detailOrigin.value=location.hash&&!location.hash.startsWith('#post-')?location.hash:'#home';window.history.pushState({},'',`#post-${post.id}`);await loadDetail(post.id,post)}
function closeDetail(){detail.value=null;const target=detailOrigin.value||'#home';history.replaceState({},'',target);view.value=target.slice(1)||'home'}
async function submitComment(e){const f=new FormData(e.currentTarget),content=f.get('comment').trim();if(!content)return;busy.value=true;try{const c=demoMode.value?{id:`local-c-${Date.now()}`,author:viewer.value,content,age:'刚刚'}:(await api.comment(detail.value.id,content)).data;comments.value.push(c);detail.value.comments++;e.currentTarget.reset();announce('回复已发布')}catch(err){announce(err.message)}finally{busy.value=false}}
async function runSearch(){if(!query.value.trim())return;view.value='discover';sectionError.value='';try{const r=await api.search(query.value.trim());results.value=r.data.posts||[];resultUsers.value=r.data.users||[];resultTags.value=r.data.tags||[]}catch(e){sectionError.value=e.message}}
function chooseCategory(category){query.value=category.name;runSearch()}
async function toggleBookmark(post){requireAuth(async()=>{const was=!!post.bookmarked;try{await api.bookmark(post.id,was);post.bookmarked=!was;if(was&&view.value==='saved')bookmarks.value=bookmarks.value.filter(p=>p.id!==post.id);announce(was?'已取消收藏':'已收藏')}catch(e){announce(e.message)}})}
async function toggleFollow(user){requireAuth(async()=>{try{await api.follow(user.id,!!user.following);user.following=!user.following;announce(user.following?'已关注':'已取消关注')}catch(e){announce(e.message)}})}
async function openPublicProfile(id,push=true){sectionError.value='';detail.value=null;view.value='profile';if(push)history.pushState({},'',`#user-${id}`);try{publicProfile.value=(await api.profileById(id)).data}catch(e){sectionError.value=e.message}}
async function loadSocial(relation){try{socialList.value=(await api[relation](publicProfile.value.id)).data||[]}catch(e){sectionError.value=e.message}}
async function toggleBlockProfile(){requireAuth(async()=>{try{await api.block(publicProfile.value.id,publicProfile.value.blocked_by_me);publicProfile.value.blocked_by_me=!publicProfile.value.blocked_by_me;publicProfile.value.following=false;announce(publicProfile.value.blocked_by_me?'已屏蔽':'已解除屏蔽')}catch(e){announce(e.message)}})}
async function openCategory(category){feedFilters.value={categoryId:category.id};view.value='home';history.replaceState({},'','#home');await loadFeed()}
async function toggleCategoryFollow(category){requireAuth(async()=>{try{await api.followCategory(category.id,!!category.followed);category.followed=!category.followed;announce(category.followed?'已关注分类':'已取消关注')}catch(e){announce(e.message)}})}
async function revokeDevice(session){if(!confirm('确定撤销这个设备会话吗？'))return;try{await api.revokeSession(session.id);deviceSessions.value=deviceSessions.value.filter(s=>s.id!==session.id);if(session.current){clearSession();viewer.value=null;navigate('home')}announce('设备会话已撤销')}catch(e){announce(e.message)}}
async function messageUser(user){requireAuth(async()=>{try{const conversation=(await api.createConversation(user.id)).data;await navigate('messages');await loadConversations();await openConversation(conversation)}catch(e){announce(e.message)}})}
async function saveProfile(e){const f=new FormData(e.currentTarget);busy.value=true;try{const r=await api.updateProfile({display_name:f.get('display_name'),bio:f.get('bio')});viewer.value=normalizeUser(r.data);sessionStorage.setItem('fanbbs_user',JSON.stringify(viewer.value));announce('资料已保存')}catch(err){sectionError.value=err.message}finally{busy.value=false}}
async function markAllRead(){try{await api.readNotifications(notifications.value.filter(n=>!n.read_at).map(n=>n.id));notifications.value.forEach(n=>n.read_at=n.read_at||new Date().toISOString());announce('通知已全部标为已读')}catch(e){announce(e.message)}}
async function loadConversations(){messageMode.value='conversations';activeConversation.value=null;try{const r=await api.conversations();conversations.value=r.data||[];conversationCursor.value=r.page?.next_cursor||'';await pollEvents();clearInterval(eventTimer);eventTimer=setInterval(pollEvents,15000)}catch(e){sectionError.value=e.message}}
async function loadMoreConversations(){if(!conversationCursor.value)return;try{const r=await api.conversations(conversationCursor.value);conversations.value.push(...(r.data||[]));conversationCursor.value=r.page?.next_cursor||''}catch(e){sectionError.value=e.message}}
async function openConversation(item){activeConversation.value=item;try{const r=await api.messages(item.id);messages.value=(r.data||[]).slice().reverse();messageCursor.value=r.page?.next_cursor||'';const latest=messages.value.at(-1);if(latest)await api.markConversationRead(item.id,latest.id)}catch(e){sectionError.value=e.message}}
async function leaveConversation(){if(!confirm('确定离开这个会话吗？'))return;try{await api.leaveConversation(activeConversation.value.id);conversations.value=conversations.value.filter(c=>c.id!==activeConversation.value.id);activeConversation.value=null;messages.value=[];announce('已离开会话')}catch(e){announce(e.message)}}
async function loadOlderMessages(){if(!messageCursor.value)return;try{const r=await api.messages(activeConversation.value.id,messageCursor.value);messages.value.unshift(...(r.data||[]).slice().reverse());messageCursor.value=r.page?.next_cursor||''}catch(e){sectionError.value=e.message}}
async function pollEvents(){try{const r=await api.events(eventCursor.value);eventCursor.value=r.page?.next_cursor||eventCursor.value;if((r.data||[]).some(e=>e.type==='message')&&activeConversation.value){const latest=await api.messages(activeConversation.value.id);messages.value=(latest.data||[]).slice().reverse()}}catch(e){if(e.status===401){clearInterval(eventTimer);return}sectionError.value=e.message}}
async function sendMessage(e){const f=new FormData(e.currentTarget),content=f.get('message').trim();if(!content)return;busy.value=true;try{const sent=(await api.sendMessage(activeConversation.value.id,content)).data;messages.value.push(sent);e.currentTarget.reset()}catch(err){sectionError.value=err.message}finally{busy.value=false}}
async function moderate(item,decision){const reason=prompt('请填写审核理由');if(!reason)return;try{await api.moderate(item.id,decision,reason);adminQueue.value=adminQueue.value.filter(x=>x.id!==item.id);announce('审核决定已记录')}catch(e){announce(e.message)}}
async function loadAdmin(mode){adminMode.value=mode;sectionError.value='';try{if(mode==='reports')adminQueue.value=(await api.adminReview()).data||[];if(mode==='users')adminUsers.value=(await api.adminUsers()).data||[];if(mode==='content')adminContent.value=(await api.adminContent(adminContentFilter.value)).data||[];if(mode==='taxonomy'){const [c,t]=await Promise.all([api.categories(),api.tags()]);adminTaxonomy.value={categories:c.data||[],tags:t.data||[]}}}catch(e){sectionError.value=e.message}}
async function changeUserStatus(user){const status=user.status==='active'?'suspended':'active',reason=prompt(`请填写${status==='active'?'恢复':'停用'}理由`);if(!reason)return;try{await api.setUserStatus(user.id,status,reason);user.status=status;announce('用户状态已更新')}catch(e){announce(e.message)}}
async function createTaxonomy(kind){const name=prompt(`新${kind==='category'?'分类':'标签'}名称`);if(!name)return;const slug=prompt('英文 slug');if(!slug)return;try{const r=kind==='category'?await api.createCategory({name,slug}):await api.createTag({name,slug});adminTaxonomy.value[kind==='category'?'categories':'tags'].push(r.data);announce('已创建')}catch(e){announce(e.message)}}
async function editTaxonomy(kind,item){const name=prompt('修改名称',item.name);if(!name)return;const slug=prompt('修改 slug',item.slug);if(!slug)return;try{const r=kind==='category'?await api.updateCategory(item.id,{name,slug}):await api.updateTag(item.id,{name,slug});Object.assign(item,r.data);announce('已更新')}catch(e){announce(e.message)}}
async function removeTaxonomy(kind,item){if(!confirm(`确定删除 ${item.name} 吗？`))return;const reason=prompt('请填写删除理由');if(!reason)return;try{kind==='category'?await api.deleteCategory(item.id,reason):await api.deleteTag(item.id,reason);const key=kind==='category'?'categories':'tags';adminTaxonomy.value[key]=adminTaxonomy.value[key].filter(x=>x.id!==item.id);announce('已删除')}catch(e){announce(e.message)}}
async function loadHomepageAdmin(){adminMode.value='homepage';try{homepageAdmin.value=(await api.adminHomepage()).data}catch(e){sectionError.value=e.message}}
async function saveHomepage(e){const f=new FormData(e.currentTarget);try{const payload=JSON.parse(f.get('payload'));homepageAdmin.value=(await api.updateHomepage(homepageAdmin.value.version,{status:f.get('status'),...payload})).data;announce('首页配置已保存')}catch(e){sectionError.value=e.message}}
async function loadShop(){view.value='shop';history.replaceState({},'','#shop');sectionError.value='';try{const [types,list,basket]=await Promise.all([api.productTypes(),api.products(),viewer.value?api.cart():Promise.resolve({data:[]})]);productTypes.value=types.data||[];products.value=list.data||[];cart.value=basket.data||[]}catch(e){sectionError.value=e.message}}
async function addCart(product){requireAuth(async()=>{try{const existing=cart.value.find(x=>x.product.id===product.id),quantity=(existing?.quantity||0)+1;const r=await api.setCart(product.id,quantity);if(existing)Object.assign(existing,r.data);else cart.value.push(r.data);announce('已加入清单')}catch(e){announce(e.message)}})}
async function checkout(){if(!confirm('这会创建一个不含付款的本地履约订单，继续吗？'))return;try{const order=(await api.createOrder()).data;orders.value.unshift(order);cart.value=[];announce('本地订单已创建，不涉及付款')}catch(e){announce(e.message)}}
async function loadOrders(){view.value='orders';history.replaceState({},'','#orders');try{orders.value=(await api.orders()).data||[]}catch(e){sectionError.value=e.message}}
async function cancelOrder(order){const reason=prompt('取消理由');if(!reason)return;try{Object.assign(order,(await api.cancelOrder(order.id,reason)).data);announce('订单已取消，库存已释放')}catch(e){announce(e.message)}}
async function loadGamification(){view.value='gamification';history.replaceState({},'','#gamification');try{const [g,p,t,r,f]=await Promise.all([api.gamification(),api.pointEvents(),api.tasks(),api.ranks(),api.frames()]);game.value=g.data;pointEvents.value=p.data||[];tasks.value=t.data||[];ranks.value=r.data||[];frames.value=f.data||[]}catch(e){sectionError.value=e.message}}
async function checkIn(){try{await api.checkIn();await loadGamification();announce('今日签到完成')}catch(e){announce(e.message)}}
async function chooseFrame(frame){try{await api.selectFrame(frame.id);frames.value.forEach(f=>f.selected=f.id===frame.id);announce('头像框已选择')}catch(e){announce(e.message)}}
async function reportPost(post){requireAuth(async()=>{const reason=prompt('请说明举报理由（至少 5 个字）');if(!reason)return;try{await api.report('post',post.id,reason);announce('举报已提交审核')}catch(e){announce(e.message)}})}
async function editPost(post){const content=prompt('编辑帖子内容',post.content);if(content==null||content.trim()===post.content)return;try{detail.value=(await api.updatePost(post.id,post.version,content.trim())).data;const i=posts.value.findIndex(p=>p.id===post.id);if(i>=0)posts.value[i]=detail.value;announce('帖子已更新')}catch(e){announce(e.message)}}
async function deletePost(post){if(!confirm('确定删除这条帖子吗？'))return;try{await api.deletePost(post.id,post.version);posts.value=posts.value.filter(p=>p.id!==post.id);closeDetail();announce('帖子已删除')}catch(e){announce(e.message)}}
async function editComment(comment){const content=prompt('编辑回复',comment.content);if(content==null||content.trim()===comment.content)return;try{const updated=(await api.updateComment(detail.value.id,comment.id,comment.version,content.trim())).data;const i=comments.value.findIndex(c=>c.id===comment.id);if(i>=0)comments.value[i]=updated;announce('回复已更新')}catch(e){announce(e.message)}}
async function deleteComment(comment){if(!confirm('确定删除这条回复吗？'))return;try{await api.deleteComment(detail.value.id,comment.id,comment.version);comments.value=comments.value.filter(c=>c.id!==comment.id);detail.value.comments=Math.max(0,detail.value.comments-1);announce('回复已删除')}catch(e){announce(e.message)}}
async function toggleCommentLike(comment){const key=`comment-like:${comment.id}`;if(pendingPosts.has(key))return;pendingPosts.add(key);const was=!!comment.liked;try{const r=await api.likeComment(detail.value.id,comment.id,was);comment.liked=r.data.liked;comment.like_count=r.data.like_count}catch(e){announce(e.message)}finally{pendingPosts.delete(key)}}
async function updateAvatar(e){const file=e.target.files?.[0];if(!file)return;busy.value=true;try{const r=await uploadFile(file,{avatar:true,altText:`${viewer.value.name}的头像`});viewer.value.avatar_url=r.data.url;sessionStorage.setItem('fanbbs_user',JSON.stringify(viewer.value));announce('头像已更新')}catch(err){sectionError.value=err.message}finally{busy.value=false;e.target.value=''}}
async function syncHistory(){if(location.hash.startsWith('#post-')){await loadDetail(location.hash.slice(6));return}if(location.hash.startsWith('#user-')){await openPublicProfile(location.hash.slice(6),false);return}detail.value=null;view.value=location.hash.slice(1)||'home'}
onMounted(async()=>{try{viewer.value=normalizeUser(JSON.parse(sessionStorage.getItem('fanbbs_user')||'null')||{});if(!viewer.value.handle)viewer.value=null;if(viewer.value){const r=await api.profile();viewer.value=normalizeUser(r.data);sessionStorage.setItem('fanbbs_user',JSON.stringify(viewer.value))}}catch{clearSession();viewer.value=null}try{homepage.value=(await api.homepage()).data.payload||homepage.value}catch{}await loadFeed();await syncHistory();addEventListener('popstate',syncHistory)})
onUnmounted(()=>{removeEventListener('popstate',syncHistory);clearInterval(eventTimer)})
</script>

<template>
  <a class="skip" href="#feed">跳到内容</a>
  <header class="topbar"><button class="icon-button menu" aria-label="打开菜单">☰</button><button class="brand" @click="navigate('home')">FanBBS</button><label class="search"><span>⌕</span><span class="sr-only">搜索社区</span><input v-model="query" placeholder="搜索帖子、用户或内容" @keyup.enter="runSearch"></label><div class="top-actions"><button class="icon-button" aria-label="发布" @click="requireAuth(()=>composerOpen=true)">✎</button><button class="icon-button" aria-label="通知" @click="requireAuth(()=>navigate('messages'))">♢<i></i></button><button v-if="!viewer" class="text-button" @click="authMode='login';loginOpen=true">登录</button><button v-if="!viewer" class="primary small" @click="authMode='register';loginOpen=true">注册</button><button v-else class="user-chip" @click="navigate('me')">{{ viewer.name }}</button></div></header>
  <aside class="rail" aria-label="主导航"><nav><button :class="{active:view==='home'}" @click="navigate('home')"><b>⌂</b><span>首页</span></button><button :class="{active:view==='discover'}" @click="navigate('discover')"><b>◉</b><span>发现</span></button><button :class="{active:view==='shop'}" @click="loadShop"><b>◇</b><span>商城</span></button><button @click="changeTab('following');navigate('home')"><b>♙</b><span>关注</span></button><button :class="{active:view==='messages'}" @click="requireAuth(()=>navigate('messages'))"><b>▱</b><span>消息</span></button><button :class="{active:view==='saved'}" @click="requireAuth(()=>navigate('saved'))"><b>▯</b><span>收藏</span></button></nav><button class="rail-compose" aria-label="发布新帖" @click="requireAuth(()=>composerOpen=true)">＋</button></aside>
  <main class="shell" id="feed">
    <section v-if="!detail&&view==='home'" class="timeline" aria-labelledby="feed-heading"><h1 id="feed-heading" class="sr-only">社区动态</h1>
      <div v-if="homepage.announcements?.length" class="announcements"><a v-for="a in homepage.announcements.filter(x=>x.enabled)" :key="a.id" :href="a.link_url||'#'">{{a.text}}</a></div><div v-if="homepage.carousel?.some(x=>x.enabled)" class="home-carousel"><a v-for="slide in homepage.carousel.filter(x=>x.enabled)" :key="slide.id" :href="slide.link_url||'#'"><img v-if="slide.media_url" :src="slide.media_url" :alt="slide.title"><div><b>{{slide.title}}</b><p>{{slide.summary}}</p></div></a></div><div class="tabs" role="tablist" aria-label="动态类型"><button v-for="t in tabs" :key="t[0]" role="tab" :aria-selected="tab===t[0]" @click="changeTab(t[0])">{{t[1]}}</button></div>
      <div v-if="!viewer" class="join"><div><h2>加入对话</h2><p>登录后即可发帖、点赞、转发和回复。</p><button class="primary" @click="authMode='login';loginOpen=true">登录</button><button class="outline" @click="authMode='register';loginOpen=true">注册</button></div><div class="people" aria-hidden="true"><span>••</span><i></i><i></i><i></i></div></div>
      <p v-if="demoMode" class="notice" role="status">后端暂不可用，正在展示本地预览数据</p>
      <div v-if="status==='loading'" class="skeletons" aria-label="正在加载"><div v-for="n in 5" :key="n" class="skeleton"></div></div>
      <div v-else-if="status==='error'" class="empty" role="alert"><h2>动态加载失败</h2><p>{{error}}</p><button class="primary" @click="loadFeed">重试</button></div>
      <div v-else-if="status==='empty'" class="empty"><h2>这里还没有动态</h2><p>成为第一个开启对话的人。</p><button class="primary" @click="requireAuth(()=>composerOpen=true)">发布第一帖</button></div>
      <article v-for="p in visiblePosts" :key="p.id" class="post" @click.self="openDetail(p)"><div v-if="p.repostedBy" class="repost-label">↻ {{p.repostedBy}} 转发了</div><div class="avatar" aria-hidden="true">{{p.avatar||p.author.name[0]}}</div><div class="post-body"><header><button class="author" @click="openPublicProfile(p.author.id)">{{p.author.name}}</button><span>@{{p.author.handle}} · {{p.age}}</span><button class="more" aria-label="更多操作">⋮</button></header><button class="post-content" @click="openDetail(p)">{{p.content}}</button><div v-if="Array.isArray(p.media)&&p.media.length" class="media-grid"><template v-for="m in p.media" :key="m.id"><video v-if="m.mime_type?.startsWith('video/')" :src="m.url" controls preload="metadata"></video><img v-else :src="m.url" :alt="m.alt_text||'帖子图片'" loading="lazy"></template></div><div v-else-if="p.media" class="media" role="img" :aria-label="p.mediaAlt"><span class="sun"></span><span class="skyline">▂▃▅▂▆▃▂</span><span class="river"></span></div><footer><button @click="openDetail(p)" :aria-label="`${p.comments} 条回复`">◯ <span>{{p.comments}}</span></button><button :class="{liked:p.reposted}" @click="repost(p)">↻ <span>{{p.reposts}}</span></button><button :class="{liked:p.liked}" @click="toggleLike(p)">♡ <span>{{p.likes}}</span></button><button :class="{liked:p.bookmarked}" @click="toggleBookmark(p)" aria-label="收藏">▯</button><span class="views">▥ {{p.views}}</span></footer></div></article>
      <div v-if="status==='ready'&&!visiblePosts.length" class="empty"><h2>没有匹配的动态</h2><p>换一个关键词试试。</p><button class="outline" @click="query=''">清除搜索</button></div>
    </section>
    <section v-else-if="!detail&&view==='discover'" class="section-page"><h1>发现</h1><form class="discover-search" @submit.prevent="runSearch"><label for="discover-q">搜索社区</label><div><input id="discover-q" v-model="query" placeholder="帖子、用户或内容"><button class="primary">搜索</button></div></form><p v-if="sectionError" class="form-error" role="alert">{{sectionError}}</p><div class="chips" aria-label="分类"><span v-for="c in categories" :key="c.id" class="category-chip"><button @click="openCategory(c)">{{c.name}}</button><button :aria-label="`${c.followed?'取消关注':'关注'} ${c.name}`" @click="toggleCategoryFollow(c)">{{c.followed?'★':'☆'}}</button></span></div><h2 v-if="results.length">帖子</h2><article v-for="p in results" :key="p.id" class="compact-result"><button @click="openDetail(p)"><b>{{p.author.name}}</b><span>@{{p.author.handle}}</span><p>{{p.content}}</p></button><button class="outline" @click="toggleBookmark(p)">{{p.bookmarked?'取消收藏':'收藏'}}</button></article><h2 v-if="resultUsers.length">用户</h2><article v-for="u in resultUsers" :key="u.id" class="compact-result user-result"><div><b>{{u.display_name||u.name}}</b><span>@{{u.handle}}</span><p>{{u.bio}}</p></div><div class="user-result-actions"><button class="text-button" @click="messageUser(u)">私信</button><button class="outline" @click="toggleFollow(u)">{{u.following?'取消关注':'关注'}}</button></div></article><h2 v-if="resultTags.length">标签</h2><div class="chips"><button v-for="t in resultTags" :key="t.id" @click="query=t.name;runSearch()"># {{t.name}}</button></div><p v-if="!results.length&&!resultUsers.length&&!resultTags.length" class="empty-copy">输入关键词，发现帖子与社区成员。</p></section>
    <section v-else-if="!detail&&view==='saved'" class="section-page"><h1>我的收藏</h1><p v-if="sectionError" class="form-error">{{sectionError}}</p><article v-for="p in bookmarks" :key="p.id" class="compact-result"><button @click="openDetail(p)"><b>{{p.author.name}}</b><p>{{p.content}}</p></button><button class="outline" @click="toggleBookmark(p)">取消收藏</button></article><p v-if="!bookmarks.length" class="empty-copy">还没有收藏帖子。</p></section>
    <section v-else-if="!detail&&view==='messages'" class="section-page"><div class="section-heading"><h1>消息</h1><div class="message-tabs"><button :class="{active:messageMode==='notifications'}" @click="messageMode='notifications';activeConversation=null">通知</button><button :class="{active:messageMode==='conversations'}" @click="loadConversations">私信</button></div><button v-if="messageMode==='notifications'" class="text-button" @click="markAllRead">全部已读</button></div><p v-if="sectionError" class="form-error">{{sectionError}}</p><template v-if="messageMode==='notifications'"><article v-for="n in notifications" :key="n.id" class="notification" :class="{unread:!n.read_at}"><b>{{n.title||'社区通知'}}</b><p>{{n.message||n.type}}</p><time>{{n.created_at}}</time></article><p v-if="!notifications.length" class="empty-copy">暂时没有新通知。</p></template><template v-else-if="!activeConversation"><button v-for="c in conversations" :key="c.id" class="conversation-row" @click="openConversation(c)"><b>{{c.other_user?.display_name||c.title||'私信会话'}}</b><p>{{c.last_message?.content||'开始对话'}}</p><time>{{c.updated_at}}</time></button><p v-if="!conversations.length" class="empty-copy">还没有私信会话。</p><button v-if="conversationCursor" class="outline load-more" @click="loadMoreConversations">加载更多会话</button></template><template v-else><button class="back" @click="activeConversation=null">← 返回会话</button><button v-if="messageCursor" class="text-button load-more" @click="loadOlderMessages">加载更早消息</button><div class="message-thread"><article v-for="m in messages" :key="m.id" class="message-bubble" :class="{mine:m.sender_id===viewer?.id}"><p>{{m.content}}</p><time>{{m.created_at}}</time></article></div><form class="message-compose" @submit.prevent="sendMessage"><label class="sr-only" for="private-message">发送私信</label><input id="private-message" name="message" maxlength="2000" required placeholder="写一条消息…"><button class="primary" :disabled="busy">发送</button></form></template></section>
    <section v-else-if="!detail&&view==='me'" class="section-page"><div class="section-heading"><h1>个人资料</h1><button class="text-button" @click="logout">退出登录</button></div><p v-if="sectionError" class="form-error">{{sectionError}}</p><label class="avatar-upload">更新头像<input type="file" accept="image/jpeg,image/png,image/webp,image/gif" @change="updateAvatar"></label><form class="profile-form" @submit.prevent="saveProfile"><label for="display-name">显示名称</label><input id="display-name" name="display_name" :value="viewer?.name" required maxlength="40"><label for="bio">简介</label><textarea id="bio" name="bio" :value="viewer?.bio" maxlength="240"></textarea><button class="primary" :disabled="busy">保存资料</button></form><div class="profile-shortcuts"><button class="outline" @click="loadOrders">我的订单</button><button class="outline" @click="loadGamification">等级与积分</button><button class="outline" @click="loadShop">本地商城</button></div><section class="device-sessions"><h2>设备会话</h2><article v-for="session in deviceSessions" :key="session.id"><div><b>{{session.current?'当前设备':'其他设备'}}</b><p>创建于 {{session.created_at}}</p></div><button class="outline" @click="revokeDevice(session)">撤销</button></article></section><button v-if="viewer?.role==='moderator'||viewer?.role==='admin'" class="outline admin-link" @click="navigate('admin')">进入审核台</button></section>
    <section v-else-if="!detail&&view==='shop'" class="section-page"><div class="section-heading"><h1>本地商城</h1><button v-if="viewer" class="outline" @click="loadOrders">我的订单</button></div><p class="notice">这里只创建不含付款的本地履约订单；支付、现金钱包、VIP 和外部物流均未启用。</p><p v-if="sectionError" class="form-error">{{sectionError}}</p><div class="product-grid"><article v-for="p in products" :key="p.id"><h2>{{p.name}}</h2><p>{{p.description}}</p><span>库存 {{p.inventory}}</span><button class="primary" :disabled="p.inventory<1" @click="addCart(p)">加入清单</button></article></div><aside v-if="viewer&&cart.length" class="cart-panel"><h2>履约清单</h2><p v-for="item in cart" :key="item.product.id">{{item.product.name}} × {{item.quantity}}</p><button class="primary" @click="checkout">创建本地订单</button></aside></section>
    <section v-else-if="!detail&&view==='orders'" class="section-page"><h1>我的订单</h1><p class="notice">订单不含付款承诺。</p><article v-for="o in orders" :key="o.id" class="order-row"><div><b>{{o.id}}</b><p>{{o.items.map(i=>`${i.name} × ${i.quantity}`).join('、')}}</p><span>{{o.status}} <template v-if="o.tracking_code">· {{o.fulfillment_carrier}} {{o.tracking_code}}</template></span></div><button v-if="o.status==='created'" class="outline" @click="cancelOrder(o)">取消</button></article><p v-if="!orders.length" class="empty-copy">还没有订单。</p></section>
    <section v-else-if="!detail&&view==='gamification'" class="section-page"><div class="section-heading"><h1>等级与积分</h1><button class="primary" @click="checkIn">今日签到</button></div><p class="notice">积分是社区内的非现金荣誉值，不能购买、兑换现金或转账。</p><div v-if="game" class="game-summary"><b>{{game.level_name}} · {{game.title}}</b><span>{{game.points_balance}} 积分 · 排名 {{game.rank}}</span></div><h2>任务</h2><article v-for="t in tasks" :key="t.id" class="task-row"><div><b>{{t.name}}</b><p>{{t.description}}</p></div><span>{{t.reward_points}} 分</span></article><h2>头像框</h2><div class="frame-grid"><button v-for="f in frames" :key="f.id" :disabled="!f.entitled" :class="{selected:f.selected}" @click="chooseFrame(f)">{{f.name}}</button></div><h2>排行榜</h2><ol><li v-for="r in ranks" :key="r.user_id">{{r.display_name}} · {{r.lifetime_points}} 分</li></ol></section>
    <section v-else-if="!detail&&view==='profile'" class="section-page public-profile"><p v-if="sectionError" class="form-error">{{sectionError}}</p><template v-if="publicProfile"><div class="profile-cover" :style="publicProfile.cover_url?{backgroundImage:`url(${publicProfile.cover_url})`}:{}"></div><div class="profile-head"><div class="avatar">{{publicProfile.name?.[0]}}</div><div><h1>{{publicProfile.name}}</h1><p>@{{publicProfile.handle}}</p></div><div v-if="viewer?.id!==publicProfile.id" class="profile-actions"><button class="primary" @click="toggleFollow(publicProfile)">{{publicProfile.following?'取消关注':'关注'}}</button><button class="outline" @click="messageUser(publicProfile)">私信</button><button class="text-button" @click="toggleBlockProfile">{{publicProfile.blocked_by_me?'解除屏蔽':'屏蔽'}}</button></div></div><p>{{publicProfile.bio}}</p><div class="profile-counts"><button @click="loadSocial('followers')"><b>{{publicProfile.follower_count}}</b> 关注者</button><button @click="loadSocial('following')"><b>{{publicProfile.following_count}}</b> 正在关注</button><span><b>{{publicProfile.post_count}}</b> 帖子</span></div><article v-for="u in socialList" :key="u.id" class="compact-result"><button @click="openPublicProfile(u.id)"><b>{{u.display_name}}</b> @{{u.handle}}</button><button class="outline" @click="toggleFollow(u)">{{u.following?'取消关注':'关注'}}</button></article></template></section>
    <section v-else-if="!detail&&view==='admin'" class="section-page"><h1>社区管理</h1><p>服务端角色权限和不可变审计是所有管理操作的最终边界。</p><div class="admin-tabs"><button v-for="m in [['reports','举报'],['users','用户'],['content','内容'],['taxonomy','分类标签'],['homepage','首页配置']]" :key="m[0]" :class="{active:adminMode===m[0]}" @click="m[0]==='homepage'?loadHomepageAdmin():loadAdmin(m[0])">{{m[1]}}</button></div><p v-if="sectionError" class="form-error">{{sectionError}}</p><template v-if="adminMode==='reports'"><article v-for="item in adminQueue" :key="item.id" class="review-item"><div><b>{{item.target_type}} · {{item.reason}}</b><p>{{item.status}}</p></div><button class="outline" @click="moderate(item,'dismiss')">驳回举报</button><button class="primary" @click="moderate(item,'remove_content')">移除内容</button></article><p v-if="!adminQueue.length" class="empty-copy">审核队列已清空。</p></template><template v-else-if="adminMode==='users'"><article v-for="u in adminUsers" :key="u.id" class="review-item"><div><b>{{u.display_name}} @{{u.handle}}</b><p>{{u.role}} · {{u.status}}</p></div><button class="outline" @click="changeUserStatus(u)">{{u.status==='active'?'停用':'恢复'}}</button></article></template><template v-else-if="adminMode==='content'"><form class="admin-filters" @submit.prevent="loadAdmin('content')"><input v-model="adminContentFilter.q" placeholder="搜索内容"><select v-model="adminContentFilter.status"><option value="published">已发布</option><option value="deleted">已删除</option><option value="draft">草稿</option></select><select v-model="adminContentFilter.type"><option value="">全部类型</option><option value="post">帖子</option><option value="comment">评论</option></select><button class="outline">筛选</button></form><article v-for="p in adminContent" :key="p.id" class="review-item"><div><b>{{p.title}}</b><p>{{p.author?.display_name}} · {{p.status}} · {{p.visibility}}</p></div><button class="outline" @click="openDetail(p)">查看</button></article></template><template v-else-if="adminMode==='taxonomy'"><div class="taxonomy-admin"><section><div class="section-heading"><h2>分类</h2><button class="outline" @click="createTaxonomy('category')">新建</button></div><div v-for="c in adminTaxonomy.categories" :key="c.id" class="taxonomy-row"><span>{{c.name}} · {{c.slug}}</span><span><button @click="editTaxonomy('category',c)">编辑</button><button @click="removeTaxonomy('category',c)">删除</button></span></div></section><section><div class="section-heading"><h2>标签</h2><button class="outline" @click="createTaxonomy('tag')">新建</button></div><div v-for="t in adminTaxonomy.tags" :key="t.id" class="taxonomy-row"><span>{{t.name}} · {{t.slug}}</span><span><button @click="editTaxonomy('tag',t)">编辑</button><button @click="removeTaxonomy('tag',t)">删除</button></span></div></section></div></template><template v-else><form v-if="homepageAdmin" class="homepage-editor" @submit.prevent="saveHomepage"><label>状态<select name="status" :value="homepageAdmin.status"><option value="draft">草稿</option><option value="published">发布</option></select></label><label>首页 JSON<textarea name="payload" :value="JSON.stringify(homepageAdmin.payload,null,2)" spellcheck="false"></textarea></label><p>版本 {{homepageAdmin.version}} · 保存使用 If-Match 防止覆盖其他管理员修改</p><button class="primary">保存首页配置</button></form></template></section>
    <section v-else class="detail"><button class="back" @click="closeDetail">← 返回动态</button><button class="report-button" @click="reportPost(detail)">举报</button><h1 tabindex="-1" class="detail-title">帖子详情</h1><div v-if="viewer?.id===detail.author.id" class="owner-actions"><button class="outline" @click="editPost(detail)">编辑</button><button class="danger-button" @click="deletePost(detail)">删除</button></div><article class="post detail-post"><div class="avatar">{{detail.avatar}}</div><div class="post-body"><header><b>{{detail.author.name}}</b><span>@{{detail.author.handle}} · {{detail.age}}</span></header><p class="detail-copy">{{detail.content}}</p><div v-if="Array.isArray(detail.media)&&detail.media.length" class="media-grid"><template v-for="m in detail.media" :key="m.id"><video v-if="m.mime_type?.startsWith('video/')" :src="m.url" controls preload="metadata"></video><img v-else :src="m.url" :alt="m.alt_text||'帖子图片'" loading="lazy"></template></div><footer><button>◯ {{detail.comments}}</button><button>↻ {{detail.reposts}}</button><button @click="toggleLike(detail)">♡ {{detail.likes}}</button></footer></div></article><section class="comments"><h2>回复</h2><form v-if="viewer" @submit.prevent="submitComment"><label for="comment">加入对话</label><textarea id="comment" name="comment" required maxlength="1000" placeholder="写下你的回复…"></textarea><button class="primary" :disabled="busy">回复</button></form><button v-else class="outline login-reply" @click="loginOpen=true">登录后回复</button><article v-for="c in comments" :key="c.id" class="comment"><div class="avatar">{{c.author.name[0]}}</div><div><b>{{c.author.name}}</b> <span>@{{c.author.handle}} · {{c.age}}</span><p>{{c.content}}</p><div class="comment-actions"><button :class="{liked:c.liked}" @click="toggleCommentLike(c)">♡ {{c.like_count||0}}</button><template v-if="viewer?.id===c.author.id"><button @click="editComment(c)">编辑</button><button @click="deleteComment(c)">删除</button></template></div></div></article><p v-if="!comments.length">还没有回复。</p></section></section>
  </main>
  <button class="mobile-fab" aria-label="发布新帖" @click="requireAuth(()=>composerOpen=true)">＋<small>发布</small></button>
  <nav class="bottom-nav" aria-label="移动端主导航"><button :class="{active:view==='home'}" @click="navigate('home')"><b>⌂</b><span>首页</span></button><button :class="{active:view==='discover'}" @click="navigate('discover')"><b>◉</b><span>发现</span></button><button :class="{active:view==='messages'}" @click="requireAuth(()=>navigate('messages'))"><b>▱</b><span>消息</span></button><button :class="{active:view==='me'}" @click="requireAuth(()=>navigate('me'))"><b>♙</b><span>我的</span></button></nav>

  <div v-if="loginOpen" class="backdrop" @mousedown.self="closeDialog('login')"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="login-title"><button class="dialog-close" aria-label="关闭" @click="closeDialog('login')">×</button><h2 id="login-title">{{authMode==='login'?'欢迎回来':'创建账号'}}</h2><p>{{authMode==='login'?'登录后加入 FanBBS 的每一次对话':'用本地账号加入社区'}}</p><form v-if="authMode==='login'" @submit.prevent="doLogin"><label for="identity">用户名或邮箱</label><input id="identity" name="identity" autocomplete="username" required><label for="password">密码</label><input id="password" name="password" type="password" autocomplete="current-password" required><p v-if="loginError" class="form-error" role="alert">{{loginError}}</p><button class="primary wide" :disabled="busy">{{busy?'正在登录…':'登录'}}</button><button type="button" class="text-button" @click="authMode='register';loginError=''">还没有账号？注册</button></form><form v-else @submit.prevent="doRegister"><label for="new-handle">用户名</label><input id="new-handle" name="handle" autocomplete="username" minlength="3" maxlength="24" required><label for="new-email">邮箱</label><input id="new-email" name="email" type="email" autocomplete="email" required><label for="new-name">显示名称</label><input id="new-name" name="display_name" maxlength="40" required><label for="new-password">密码</label><input id="new-password" name="password" type="password" autocomplete="new-password" minlength="8" required><p v-if="loginError" class="form-error" role="alert">{{loginError}}</p><button class="primary wide" :disabled="busy">{{busy?'正在创建…':'注册'}}</button><button type="button" class="text-button" @click="authMode='login';loginError=''">已有账号？登录</button></form></section></div>
  <div v-if="composerOpen" class="backdrop" @mousedown.self="closeDialog('compose')"><section class="dialog composer" role="dialog" aria-modal="true" aria-labelledby="compose-title"><button class="dialog-close" aria-label="关闭" @click="closeDialog('compose')">×</button><h2 id="compose-title">发布新帖</h2><label for="draft">分享此刻的想法</label><textarea id="draft" v-model="draft" maxlength="2000" @input="localStorage.setItem('fanbbs_draft',draft)" autofocus></textarea><label class="media-picker">添加图片或视频（最多 8 个）<input type="file" accept="image/jpeg,image/png,image/webp,image/gif,video/mp4" multiple @change="selectMedia"></label><ul v-if="selectedFiles.length" class="selected-media"><li v-for="file in selectedFiles" :key="file.name">{{file.name}}</li></ul><p v-if="error" class="form-error" role="alert">{{error}}</p><div class="compose-actions"><span>{{draft.length}} / 2000 · 草稿自动保存</span><button class="primary" :disabled="busy||!draft.trim()" @click="publish">{{busy?'发布中…':'发布'}}</button></div></section></div>
  <div class="toast" aria-live="polite">{{toast}}</div>
</template>
